import test from 'node:test';import assert from 'node:assert/strict';import {validateWebsiteData,visibleItems,blankPageBlock,pageLink} from '../../website-data.mjs';import {fixture} from './fixture.mjs';
test('v2 website supports pages, arbitrary blocks, media and independent items',()=>{const d=validateWebsiteData(fixture());assert.equal(d.pages.length,2);assert.equal(d.pages[0].blocks[0].type,'hero');assert.equal(visibleItems(d,{island:'AGATTI',kind:'PRODUCT'})[0].name,'Tuna pickle');assert.equal(d.items[0].details[0].value.en,'60 minutes');});
test('extra page links remain website-only',()=>{const d=validateWebsiteData(fixture()),link=pageLink(d.pages[1],'https://brownnoodyai-sketch.github.io/');assert.equal(new URL(link).pathname,'/page.html');assert.equal(new URL(link).searchParams.get('slug'),'about');});
test('all page blocks can be created without locking hero or island selector',()=>{for(const type of ['hero','islandSelector','text','imageText','gallery','featuredItems','reviews','faq','whatsappCta','spacer'])assert.equal(blankPageBlock(type).type,type);});
test('duplicate page slug and unsafe images fail closed',()=>{let d=fixture();d.pages.push({...structuredClone(d.pages[1]),id:'10000000-0000-4000-8000-000000000003'});assert.throws(()=>validateWebsiteData(d),/PAGE_INVALID/);d=fixture();d.pages[0].blocks[0].image='javascript:alert(1)';assert.throws(()=>validateWebsiteData(d),/IMAGE_INVALID/);});
test('inactive island cannot publish active item',()=>{const d=fixture();d.items[0].islandCode='KAVARATTI';assert.throws(()=>validateWebsiteData(d),/ITEM_ISLAND_INACTIVE/);});
